mapper.select:
SELECT id, chunk_id, embedding_model, embedding_dimension, vector_status, create_time, update_time, deleted
FROM kb_chunk_vector
WHERE deleted = 0 AND vector_status = 'success'
  AND (embedding_vector <=> CAST(#{queryVector} AS vector)) <= #{maxDistance}
ORDER BY embedding_vector <=> CAST(#{queryVector} AS vector)
LIMIT #{topK}
